input.sparql:
SELECT ?s ?class ?ts WHERE {
  ?s a brick:Electric_Powermeter .
  ?s brick:hasSubunit ?sub || { ?s a ?class . } .
  OPTIONAL { ?s ref:hasExternalReference ?ext ; ref:hasTimeseriesId ?ts . }
}

SELECT ?s ?p WHERE {
  ?s a ?p .
  FILTER (CONTAINS(LCASE(STR(?p)), "power") || CONTAINS(LCASE(STR(?p)), "electric"))
  ?s ref:hasTimeseriesId ?ts .
}

SELECT DISTINCT ?p WHERE {
  ?s a ?p .
  FILTER (CONTAINS(LCASE(STR(?p)), "power") || CONTAINS(LCASE(STR(?p)), "meter") || CONTAINS(LCASE(STR(?p)), "electric"))
}
